func xlRef(cg *port.Cells, refs *port.Cells, g int32, firstField int32, k int32) int32 {
	// The row index the k-th reference of a run of group g (the run's first-field) points at.
	return evidence.RfGet(refs, player.CgGet(cg, g, firstField)+k, 1)
}

