func TestPagesDoNotLeak(emonT *testing.T) {
	var epages *port.Cells = port.NewCells()
	var words *port.Cells = port.NewCells()
	var owords *port.Cells = port.NewCells()
	var tlines *port.Cells = port.NewCells()
	var feats *port.Cells = port.NewCells()
	var etext *port.Cells = port.NewCells()
	var refs *port.Cells = port.NewCells()
	var cg *port.Cells = port.NewCells()
	evidence.EpNew(epages, 1, 61200, 79200)
	evidence.EpNew(epages, 2, 61200, 79200)
	xlTw(words, etext, feats, 1, 7200, 10000, 10200, 11200, 0, 0, 0, model.SrText(), 0, port.TextBlob("page"))
	xlTw(words, etext, feats, 2, 7200, 10000, 10200, 11200, 0, 0, 0, model.SrText(), 0, port.TextBlob("next"))
	xlOw(owords, etext, feats, 1, 7200, 10000, 10200, 11200, 0, 0, 0, port.TextBlob("page"))
	xlOw(owords, etext, feats, 2, 7200, 10000, 10200, 11200, 0, 0, 0, port.TextBlob("mext"))
	port.AssertEq(emonT, xlAlign(epages, words, owords, tlines, feats, etext, refs, cg, 1), 1, "page 1: one group")
	port.AssertEq(emonT, player.CgGet(cg, 0, player.CgfSim()), 1000, "page")
	port.AssertEq(emonT, player.CgGet(cg, 0, 0), 1, "on page 1")
	port.AssertEq(emonT, xlAlign(epages, words, owords, tlines, feats, etext, refs, cg, 2), 1, "page 2: one group")
	port.AssertEq(emonT, player.CgGet(cg, 1, player.CgfSim()), 750, "next / mext")
	port.AssertEq(emonT, player.CgGet(cg, 1, 0), 2, "on page 2")
	port.AssertEq(emonT, xlAlign(epages, words, owords, tlines, feats, etext, refs, cg, 3), 0, "page 3: nothing")
	port.AssertEq(emonT, player.CgCount(cg), 2, "two rows")
	port.AssertEq(emonT, evidence.RfGet(refs, player.CgGet(cg, 1, player.CgfTfirst()), 1), 1, "page 2's text word is words row 1")
}

func TestALineTooLongForTheTableIsPairedGreedily(emonT *testing.T) {
	var epages *port.Cells = port.NewCells()
	var words *port.Cells = port.NewCells()
	var owords *port.Cells = port.NewCells()
	var tlines *port.Cells = port.NewCells()
	var feats *port.Cells = port.NewCells()
	var etext *port.Cells = port.NewCells()
	var refs *port.Cells = port.NewCells()
	var cg *port.Cells = port.NewCells()
	var i int32 = 0
	evidence.EpNew(epages, 1, 100000000, 79200)
	for i < 1100 {
		xlTw(words, etext, feats, 1, 1000+(i*100), 10000, 1060+(i*100), 11200, 0, 0, 0, model.SrText(), 0, port.TextBlob("w"))
		xlOw(owords, etext, feats, 1, 1005+(i*100), 10000, 1065+(i*100), 11200, 0, 0, 0, port.TextBlob("w"))
		i += 1
	}
	port.AssertEq(emonT, xlAlign(epages, words, owords, tlines, feats, etext, refs, cg, 1), 1100, "every word is a group")
	port.AssertEq(emonT, player.CgGet(cg, 1099, player.CgfOcount()), 1, "the last has its OCR word")
	port.AssertEq(emonT, xlRef(cg, refs, 1099, player.CgfOfirst(), 0), 1099, "which is the last")
	port.AssertEq(emonT, player.CgGet(cg, 500, player.CgfFlags()), 0, "paired")
}
